'use strict';
const data=REVIEW_DATA;
const views=['overview','companies','records','reviews','briefing','connections'];
const names={overview:'COMMAND CENTER',companies:'COMPANIES',records:'RECORDS',reviews:'REVIEW QUEUE',briefing:'DAILY BRIEFING',connections:'CONNECTIONS'};
const $=id=>document.getElementById(id);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nameOf=(id)=>{const r=[...data.companies,...data.properties,...data.tenants].find(x=>x.id===id);return r?.name_as_documented||r?.legal_name_as_documented||r?.address_as_documented||r?.name||id||'Not confirmed'};
function showView(view){if(!views.includes(view))return;views.forEach(v=>$(v).hidden=v!==view);document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.view===view);if(n.dataset.view===view)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});$('crumb').textContent=names[view];window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-view],[data-go]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view||b.dataset.go)));
const dialog=$('company-dialog');
document.querySelector('.close').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function evidence(items){return (items||[]).map(x=>{const doc=data.documents.find(d=>d.id===x.document_id);return '<li>'+escapeHTML(doc?.title||x.document_id)+' <span class="muted">· '+escapeHTML(x.locator)+'</span></li>'}).join('')}
function title(r){return r.name_as_documented||r.address_as_documented||r.name||r.title||r.topic||[r.borrower_label,r.lender_label].filter(Boolean).join(' · ')}
function openDetail(type,id){const r=data[type]?.find(x=>x.id===id);if(!r)return;$('dialog-title').textContent=title(r);let html='';
if(type==='companies'){html='<p>'+escapeHTML(r.status)+'</p><p>'+escapeHTML(r.notes)+'</p><h3>Related leases</h3>'+leaseLinks(data.leases.filter(l=>l.landlord_company_id===r.id))+'<p class="test-notice">Legal identity and title must be confirmed before financial mapping.</p>';}
if(type==='properties'){html='<p>'+escapeHTML(r.title_status)+'</p><p>'+escapeHTML(r.notes)+'</p><h3>Related leases</h3>'+leaseLinks(data.leases.filter(l=>l.property_ids.includes(r.id)))+'<p class="test-notice">Lease parties are not automatically recorded owners.</p>';}
if(type==='leases'){html='<dl><dt>Landlord as documented</dt><dd>'+escapeHTML(nameOf(r.landlord_company_id))+'</dd><dt>Tenant as documented</dt><dd>'+escapeHTML(nameOf(r.tenant_id))+'</dd><dt>Properties</dt><dd>'+r.property_ids.map(x=>escapeHTML(nameOf(x))).join('<br>')+'</dd><dt>Execution review</dt><dd>'+escapeHTML(r.execution_review)+'</dd></dl><h3>Documented terms</h3><dl>'+Object.entries(r.documented_terms).map(([k,v])=>'<dt>'+escapeHTML(k.replaceAll('_',' '))+'</dt><dd>'+escapeHTML(typeof v==='object'?JSON.stringify(v):v)+'</dd>').join('')+'</dl><h3>Needs review</h3><ul>'+(r.open_issues||[]).map(x=>'<li>'+escapeHTML(x)+'</li>').join('')+'</ul>';}
if(type==='loans'){html='<p>'+escapeHTML(r.status)+'</p><dl><dt>Candidate company</dt><dd>'+r.candidate_company_ids.map(x=>escapeHTML(nameOf(x))).join(', ')+'</dd><dt>Maturity as listed</dt><dd>'+escapeHTML(r.maturity_as_listed||'Not supplied')+'</dd><dt>Monthly payment as listed</dt><dd>'+escapeHTML(r.monthly_payment_as_listed==null?'Not supplied':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(r.monthly_payment_as_listed))+'</dd></dl><p class="test-notice">Schedule only. No confirmed borrower mapping, collateral, or current balance.</p>';}
if(type==='documents'){html='<p>'+escapeHTML(r.review_status)+'</p><p class="test-notice">Authoritative Google Drive link pending. This is a document reference; the original file is not uploaded to this website.</p>';}
if(type==='open_reviews'){html='<h3>Finding</h3><p>'+escapeHTML(r.finding)+'</p><h3>Next step</h3><p>'+escapeHTML(r.action)+'</p><p class="test-notice">Open · Resolve against source evidence before final submission.</p>';}
if(r.evidence?.length)html+='<h3>Source references</h3><ul class="sources">'+evidence(r.evidence)+'</ul>';$('dialog-content').innerHTML=html;dialog.showModal();}
function leaseLinks(records){return records.length?'<ul>'+records.map(r=>'<li><button class="text-button" data-detail="leases" data-id="'+r.id+'">'+escapeHTML(r.name)+'</button></li>').join('')+'</ul>':'<p>No lease matched in this test collection.</p>';}
function card(type,r){let sub=type==='companies'?'Documented entity name':type==='properties'?r.title_status:type==='leases'?r.execution_review:type==='loans'?r.status:type==='open_reviews'?r.finding:'Drive link pending';return '<button class="company record-card" data-detail="'+type+'" data-id="'+r.id+'"><span class="company-kind">'+escapeHTML(r.id)+' / '+escapeHTML(type.replaceAll('_',' '))+'</span><h3>'+escapeHTML(title(r))+'</h3><p>'+escapeHTML(sub)+'</p><span class="company-footer">Needs Review <b>↗</b></span></button>';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b){if(dialog.open)dialog.close();openDetail(b.dataset.detail,b.dataset.id)}});
$('featured-companies').innerHTML=data.companies.slice(0,3).map(x=>card('companies',x)).join('');
$('company-list').innerHTML=data.companies.map(x=>card('companies',x)).join('');
$('review-list').innerHTML=data.open_reviews.map(x=>card('open_reviews',x)).join('');
function renderRecords(){const type=$('record-type').value,q=$('record-search').value.trim().toLowerCase();const rows=data[type].filter(r=>JSON.stringify(r).toLowerCase().includes(q)||((r.tenant_id&&nameOf(r.tenant_id).toLowerCase().includes(q))||(r.landlord_company_id&&nameOf(r.landlord_company_id).toLowerCase().includes(q))));$('record-list').innerHTML=rows.length?rows.map(r=>card(type,r)).join(''):'<p>No matching records. Try another name or address.</p>';$('result-count').textContent=rows.length+' '+type+' · Test collection · Needs Review';}
$('record-type').onchange=renderRecords;$('record-search').oninput=renderRecords;renderRecords();
function ask(question){const q=question.trim();if(!q)return;$('prompt').value=q;const reply=$('reply');reply.hidden=false;let answer;if(/brief|today|focus|priorit|review/i.test(q))answer='There are 13 open review items. Start with company identity conflicts, then confirm ownership and executed lease terms. Financial integrations remain on hold. Open Review queue to address each issue separately.';else if(/connect|source|drive|calendar/i.test(q))answer='Google Drive document links need matching. QuickBooks, Gusto, banking and tax are not connected to this site. Confirm entity mapping first; then pilot one QuickBooks company with read-only access and audit logging.';else if(/compan|business|portfolio/i.test(q))answer='The test collection contains 14 company-name observations, 13 properties, 12 lease records, and 8 loan-schedule rows. Some company names may be variants of the same entity; they have not been merged.';else{const words=q.toLowerCase().split(/\s+/).filter(w=>w.length>3&&!['what','show','tell','about','with','does','have','please'].includes(w));const matches=data.leases.filter(r=>words.some(w=>(JSON.stringify(r)+' '+nameOf(r.tenant_id)).toLowerCase().includes(w)));answer=matches.length?'Related lease records: '+matches.map(r=>r.name).join(', ')+'. Open Records → Leases to inspect documented terms and unresolved issues. These are review records, not confirmed current obligations.':'This guided search uses the test collection; it is not a live AI service. Try a lease name, “Show my companies,” or “What needs review?”';}reply.textContent=answer;return answer;}
$('ask-form').addEventListener('submit',e=>{e.preventDefault();ask($('prompt').value)});document.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>ask(b.dataset.ask));
$('date').textContent=new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date()).toUpperCase();showView('overview');
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'navigate_brewer_workspace',description:'Open a Brewer Intelligence section. All records are provisional test data.',inputSchema:{type:'object',properties:{view:{type:'string',enum:views}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!views.includes(input.view)||Object.keys(input).some(k=>k!=='view'))throw new Error('Invalid view.');showView(input.view);return {view:input.view,mode:'test_collection'};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
